package com.darkkebbit;

import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

import java.awt.Color;

@ConfigGroup("darkkebbit")
public interface DarkKebbitConfig extends Config
{
	@Alpha
	@ConfigItem(
		keyName = "highlightColor",
		name = "Highlight Color",
		description = "Color of the destination bush highlight",
		position = 0
	)
	default Color highlightColor()
	{
		return new Color(0, 255, 0, 100);
	}

	@ConfigItem(
		keyName = "showLabel",
		name = "Show Label",
		description = "Show text label on the destination bush",
		position = 1
	)
	default boolean showLabel()
	{
		return true;
	}
}

package com.darkkebbit;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.OverlayUtil;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;

@Slf4j
public class DarkKebbitOverlay extends Overlay
{
	private static final Color WARNING_BG = new Color(80, 0, 0, 180);
	private static final Color WARNING_BORDER = new Color(255, 60, 60);
	private static final Color WARNING_TEXT = Color.WHITE;
	private static final int WARNING_PADDING = 8;

	private final Client client;
	private final DarkKebbitPlugin plugin;
	private final DarkKebbitConfig config;

	@Inject
	public DarkKebbitOverlay(Client client, DarkKebbitPlugin plugin, DarkKebbitConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(OverlayPriority.HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (plugin.getBushPositions().isEmpty())
		{
			return null;
		}

		if (!plugin.isRingEquipped())
		{
			renderWarning(graphics);
		}

		if (plugin.isTrailActive() && plugin.getDestinationBush() != null)
		{
			renderBushHighlight(graphics, plugin.getDestinationBush());
		}

		return null;
	}

	private void renderBushHighlight(Graphics2D graphics, WorldPoint bushPoint)
	{
		LocalPoint localPoint = LocalPoint.fromWorld(client, bushPoint);
		if (localPoint == null)
		{
			return;
		}

		Polygon tilePoly = Perspective.getCanvasTilePoly(client, localPoint);
		if (tilePoly == null)
		{
			return;
		}

		Color color = config.highlightColor();
		Color fillColor = new Color(color.getRed(), color.getGreen(), color.getBlue(), 50);

		OverlayUtil.renderPolygon(graphics, tilePoly, color, fillColor, new BasicStroke(2));

		if (config.showLabel())
		{
			Point textPoint = Perspective.getCanvasTextLocation(
				client, graphics, localPoint, "Dark kebbit", 0);
			if (textPoint != null)
			{
				OverlayUtil.renderTextLocation(graphics, textPoint, "Dark kebbit", Color.GREEN);
			}
		}
	}

	private void renderWarning(Graphics2D graphics)
	{
		String message = "Ring of Pursuit not equipped!";

		FontMetrics fm = graphics.getFontMetrics();
		int textWidth = fm.stringWidth(message);
		int textHeight = fm.getHeight();

		Rectangle canvasBounds = client.getCanvas().getBounds();
		int x = (canvasBounds.width - textWidth) / 2 - WARNING_PADDING;
		int y = 50;

		int boxWidth = textWidth + WARNING_PADDING * 2;
		int boxHeight = textHeight + WARNING_PADDING * 2;

		graphics.setColor(WARNING_BG);
		graphics.fillRect(x, y, boxWidth, boxHeight);
		graphics.setColor(WARNING_BORDER);
		graphics.setStroke(new BasicStroke(2));
		graphics.drawRect(x, y, boxWidth, boxHeight);

		graphics.setColor(WARNING_TEXT);
		graphics.drawString(message, x + WARNING_PADDING, y + WARNING_PADDING + fm.getAscent());
	}
}

package com.darkkebbit;

import com.google.inject.Provides;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

@Slf4j
@PluginDescriptor(
	name = "KebbitSense",
	description = "Sense exactly where the dark kebbit is hiding — skip the trail, go straight to the bush",
	tags = {"hunter", "kebbit", "dark", "tracking", "piscatoris"}
)
public class DarkKebbitPlugin extends Plugin
{
	static final int BUSH_OBJECT_ID = 19428;
	static final int VARBIT_TRAILS_USED = 2984;
	static final int VARBIT_DESTINATION = 2994;
	static final int DARK_KEBBIT_TRAIL_TYPE = 2;
	static final int RING_OF_PURSUIT_ID = 21126;

	@Inject
	private Client client;

	@Inject
	private DarkKebbitConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private DarkKebbitOverlay overlay;

	@Getter
	private final List<WorldPoint> bushPositions = new ArrayList<>();

	@Getter
	private WorldPoint destinationBush;

	@Getter
	private boolean trailActive;

	@Getter
	private boolean ringEquipped;

	@Provides
	DarkKebbitConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DarkKebbitConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		bushPositions.clear();
		destinationBush = null;
		trailActive = false;
		ringEquipped = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			bushPositions.clear();
			destinationBush = null;
			trailActive = false;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		if (bushPositions.isEmpty())
		{
			scanBushes();
		}

		checkRingEquipped();

		int trailsUsed = client.getVarbitValue(VARBIT_TRAILS_USED);
		int destination = client.getVarbitValue(VARBIT_DESTINATION);

		if (trailsUsed == DARK_KEBBIT_TRAIL_TYPE && destination >= 1 && destination <= bushPositions.size())
		{
			trailActive = true;
			destinationBush = bushPositions.get(destination - 1);
		}
		else
		{
			trailActive = false;
			destinationBush = null;
		}
	}

	private void scanBushes()
	{
		Tile[][][] tiles = client.getScene().getTiles();
		int plane = client.getPlane();

		if (tiles[plane] == null)
		{
			return;
		}

		List<WorldPoint> found = new ArrayList<>();

		for (Tile[] row : tiles[plane])
		{
			if (row == null)
			{
				continue;
			}

			for (Tile tile : row)
			{
				if (tile == null)
				{
					continue;
				}

				GroundObject groundObj = tile.getGroundObject();
				if (groundObj != null && groundObj.getId() == BUSH_OBJECT_ID)
				{
					found.add(groundObj.getWorldLocation());
				}

				for (GameObject obj : tile.getGameObjects())
				{
					if (obj != null && obj.getId() == BUSH_OBJECT_ID)
					{
						found.add(obj.getWorldLocation());
					}
				}
			}
		}

		found.sort(Comparator.comparingInt(WorldPoint::getY).reversed().thenComparingInt(WorldPoint::getX));
		bushPositions.addAll(found);

		if (!bushPositions.isEmpty())
		{
			log.info("Found {} dark kebbit bushes", bushPositions.size());
		}
	}

	private void checkRingEquipped()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			ringEquipped = false;
			return;
		}

		for (Item item : equipment.getItems())
		{
			if (item.getId() == RING_OF_PURSUIT_ID)
			{
				ringEquipped = true;
				return;
			}
		}

		ringEquipped = false;
	}
}
